import {createPlatform} from './platform.js';
import {createScannerUI} from './scanner-ui.js';
import {createTeamUI} from './team-ui.js';
import {firebaseConfig,appLinks} from './config.js';
import {publicRoleName} from './profile-display.js';
import {normalizeNotificationPreferences} from './notification-preferences.js';
const page=document.documentElement.dataset.page||'hub';
const rootBase=new URL('../',import.meta.url);
const asset=name=>new URL(name,appLinks.assets||new URL('assets/',rootBase)).href;
const links={hub:appLinks.hub||rootBase.href,dock:appLinks.dock||new URL('dock/',rootBase).href,scanner:appLinks.scanner||new URL('scanner/',rootBase).href};
const $=(s,p=document)=>p.querySelector(s);
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={tools:'<path d="M14 6a5 5 0 0 0-6 6L3 17a3 3 0 0 0 4 4l5-5a5 5 0 0 0 6-6l-3 3-4-4 3-3Z"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',dock:'<path d="m3 8 9-5 9 5v13H3Z"/><path d="M8 21V10h8v11M10 13h4M10 16h4"/>',message:'<path d="M21 15a3 3 0 0 1-3 3H9l-6 4V6a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3Z"/><path d="M7 8h10M7 12h7"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-4-5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 13v7h14v-7"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',moon:'<path d="M20 15A8 8 0 0 1 9 4 8 8 0 1 0 20 15Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',check:'<path d="m5 12 4 4 10-10"/>',logout:'<path d="M9 4H4v16h5m6-4 4-4-4-4m-7 4h11"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 5v6h6m3-4v5l3 2"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.dock}</svg>`;
const STATUS={no_trailer:{label:'No trailer',short:'No trailer',color:'var(--none)',next:'Shipping: bring an empty trailer.',tag:'Awaiting trailer'},empty:{label:'Empty trailer',short:'Empty',color:'var(--empty)',next:'Production: ready to begin loading.',tag:'Ready to load'},loading:{label:'Loading',short:'Loading',color:'var(--loading)',next:'Production: continue filling trailer.',tag:'In progress'},ready:{label:'Locked / ready',short:'Ready for pickup',color:'var(--ready)',next:'Shipping: pick up and replace trailer.',tag:'Pickup needed'},unconfirmed:{label:'Not yet confirmed',short:'Unconfirmed',color:'var(--none)',next:'Confirm this dock before taking action.',tag:'Needs update'}};
icons.scanner='<rect x="5" y="2" width="14" height="15" rx="3"/><path d="M8 6h8M8 10h1m2 0h1m2 0h2M9 17v5h6v-5M8 13h8"/>';
const DOCKS=['16','17','18','19'];
function storedView(key){try{return localStorage.getItem(`sujaTools.view.${key}`)==='list'?'list':'grid'}catch{return 'grid'}}
const views={hub:storedView('hub'),dock:storedView('dock')};
icons.grid='<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>';
icons.list='<path d="M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01"/>';
function viewToggle(key){return `<div class="view-toggle" role="group" aria-label="${key==='hub'?'Tools':'Docks'} view"><button type="button" data-action="view" data-id="${key}:grid" aria-pressed="${views[key]==='grid'}" aria-label="${key==='hub'?'App':'Dock card'} view" class="${views[key]==='grid'?'active':''}">${icon('grid')}<span>${key==='hub'?'Apps':'Cards'}</span></button><button type="button" data-action="view" data-id="${key}:list" aria-pressed="${views[key]==='list'}" aria-label="${key==='hub'?'Tools':'Docks'} list view" class="${views[key]==='list'?'active':''}">${icon('list')}<span>List</span></button></div>`}

let platform,state={mode:'setup',connected:false,user:null,account:null,docks:{},history:{},messages:[],users:{},roles:{}},unsubscribe;
let toastTimer,scannerUI,teamUI;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function time(t,full=false){if(!t)return 'Awaiting first update';return new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',month:full?'short':undefined,day:full?'numeric':undefined,hour:'numeric',minute:'2-digit'}).format(new Date(t))+' PT'}
function nowStamp(){return new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date())+' PT'}
function permission(p){return !!state.user&&(state.user.roleId==='master'||state.user.permissions?.includes(p))}
function dock(id){return state.docks?.[id]||{dockId:id,status:'unconfirmed',revision:0}}
function statusOf(d){return STATUS[d.status]||STATUS.unconfirmed}
function roleName(u){return publicRoleName(u?.roleId,u?.roleName||state.roles?.[u?.roleId]?.name||u?.roleId||'Team member')}
function historyEvents(id){let list=state.history?.[id]||[];if(!Array.isArray(list))list=Object.values(list);return list.filter(e=>(e.createdAt||e.timestamp||e.updatedAt)>Date.now()-72*60*60*1000).sort((a,b)=>(b.createdAt||b.timestamp||b.updatedAt)-(a.createdAt||a.timestamp||a.updatedAt))}
function allEvents(){return DOCKS.flatMap(id=>historyEvents(id).map(e=>({...e,dockId:id}))).sort((a,b)=>(b.createdAt||b.timestamp||b.updatedAt)-(a.createdAt||a.timestamp||a.updatedAt))}
function actor(e){return e.actorName||e.updatedByName||e.displayName||e.actor?.displayName||'Team member'}
function eventRole(e){return publicRoleName('',e.actorRoleName||e.actorRole||e.updatedByRole||e.roleName||e.actor?.roleName||'')}
function eventStatus(e){return e.toStatus||e.status||e.newStatus}
function roleAudienceLabel(role){
  if(role.id==='master'){
    const person=Object.values(state.users||{}).find(u=>u.roleId==='master');
    return `${publicRoleName(role.id,role.name)} — ${person?.displayName||'individual account'}`;
  }
  return role.id==='netsuite_operator'?`${role.name} team`:role.name;
}
function messageAudienceLabel(message){
  if(message.noticeType==='pending_account')return 'Account approval';
  if(message.noticeType==='scanner_overdue')return 'Scanner overdue alert';
  if(message.audienceType==='team')return 'Whole team';
  if(message.audienceType==='role')return roleAudienceLabel(state.roles?.[message.audienceId]||{id:message.audienceId,name:message.audienceName||message.audienceId});
  if(message.audienceType==='user')return state.users?.[message.audienceId]?.displayName||'Personal message';
  return message.audienceName||'Team update';
}
function unread(){return (state.messages||[]).filter(m=>!(m.read||m.readAt||m.readBy?.[state.user?.uid])).length}
async function start(){unsubscribe?.();platform?.destroy?.();platform=await createPlatform(firebaseConfig);unsubscribe=platform.subscribe(s=>{state=s;render()});render()}
function pendingCount(){return state.user?.roleId==='master'?Object.values(state.users||{}).filter(u=>!u.active&&u.approvalState!=='approved'&&(u.approvalState==='pending'||u.roleId==='viewer')).length:0}
function header(){return `<header class="topbar"><a class="brand" href="${links.hub}" aria-label="Suja Life Tools home"><img src="${asset('tools-icon.svg')}" alt=""><span class="brand-text">SUJA LIFE <small>TOOLS FOR OUR TEAM</small></span></a><nav class="main-nav" aria-label="Main navigation"><a class="nav-item ${page==='hub'?'active':''}" href="${links.hub}">${icon('home')}Tools</a><a class="nav-item ${page==='dock'?'active':''}" href="${links.dock}">${icon('dock')}Docks</a><a class="nav-item ${page==='scanner'?'active':''}" href="${links.scanner}">${icon('scanner')}Scanners</a><button class="nav-item" data-action="messages">${icon('message')}Messages ${state.user&&unread()?`<span class="badge-number">${unread()}</span>`:''}</button><button class="nav-item" data-action="team">${icon('users')}Team ${pendingCount()?`<span class="badge-number">${pendingCount()}</span>`:''}</button></nav><div class="header-actions"><button class="theme-btn" data-action="theme" aria-label="Switch to ${document.documentElement.dataset.theme==='dark'?'light':'dark'} mode">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="profile-pill" data-action="account"><span class="avatar">${escape((state.user?.displayName||state.account?.displayName)?.slice(0,1)||'S')}</span>${escape(state.user?.displayName||state.account?.displayName||'Sign in')}</button></div></header>`}
function banner(){return `${state.account&&!state.user?'<div class="pending-banner"><span>Your account is waiting for workspace setup or approval.</span><button data-action="account">View account</button></div>':''}${state.user&&!state.connected?'<div class="offline">Connection interrupted. Equipment and dock updates are unavailable until we reconnect. Check the last-update time before taking action.</div>':''}${state.error?`<div class="error">${escape(state.error.message||state.error)}</div>`:''}`}
function footer(){return `<footer class="footer"><span>SUJA LIFE TOOLS <span aria-hidden="true">·</span> Built for the way we work.</span><span>${page==='scanner'?'Scanner history retained':'Dock history: rolling 72 hours'} · Pacific time</span></footer>`}
const TOOLS=[{id:'dock',name:'Suja Dock Status',category:'Operations',art:'dock-app.webp',description:'Trailer updates, pickup notices, and dock history.',detail:'See every dock at a glance and make the next move clear.'},{id:'scanner',name:'Suja Scanner Status',category:'Equipment',art:'scanner-app.svg',description:'Check scanners in and out. Track every handoff.',detail:'Know who has each scanner, where it is, and whether it is ready to use.'}];
function toolCard(tool){return `<article class="tool-card"><img class="app-icon" src="${asset(tool.art)}" alt="${escape(tool.name)} app artwork"><div class="tool-body"><span class="label"><span class="dot"></span>${tool.category}</span><h3>${tool.name}</h3><p>${tool.detail}</p><div class="button-row"><a class="btn" href="${links[tool.id]}">Open tool ${icon('arrow')}</a><button class="btn quiet" data-action="share" data-id="${tool.id}" aria-label="Share ${tool.name}">${icon('share')}</button></div></div></article>`}
function toolList(){return `<div class="tool-list card" role="list" aria-label="Work tools">${TOOLS.map(tool=>`<article class="tool-list-row" role="listitem"><img src="${asset(tool.art)}" alt=""><div class="tool-list-copy"><span class="label">${tool.category}</span><h3>${tool.name}</h3><p>${tool.description}</p></div><div class="tool-list-actions"><a class="btn small" href="${links[tool.id]}">Open ${icon('arrow')}</a><button class="btn quiet small" data-action="share" data-id="${tool.id}" aria-label="Share ${tool.name}">${icon('share')}</button></div></article>`).join('')}</div>`}
function hub(){
 const scanners=Object.values(state.scanners||{}),available=scanners.filter(s=>s.checkoutStatus==='checked_in'&&s.condition==='good').length,out=scanners.filter(s=>s.checkoutStatus==='checked_out').length;
 return `<div class="contextbar"><span class="eyebrow"><span class="dot"></span>Our team. Connected.</span><span class="clock-note">${escape(nowStamp())}</span></div><section class="hero"><img class="hero-img" src="${asset('hub-hero.webp')}" alt="Illustrated Suja workplace with fresh juice, warehouse tools, and connected operations"><div class="hero-copy"><span class="eyebrow">Welcome to your workspace</span><h1>Good work starts with the right tools.</h1><p>One home for the tools that help our team stay in sync and keep the day moving.</p><a class="btn" href="${links.scanner}">Open scanner status ${icon('arrow')}</a></div></section><div class="section-title"><div><h2>Your tools</h2><p>A shared workspace. One login across every tool.</p></div><div class="section-controls"><span class="label">2 tools</span>${viewToggle('hub')}</div></div><div class="hub-grid hub-tools-grid ${views.hub==='list'?'hub-list-view':''}">${views.hub==='list'?toolList():TOOLS.map(toolCard).join('')}<aside class="team-summary card"><div><h3>Connected by the work we do.</h3><p>Shared accounts, personal messages, and assigned roles across every tool.</p><div class="role-pills"><span class="role-pill">Operator</span><span class="role-pill">Forklift driver</span><span class="role-pill">Lead</span><span class="role-pill">Supervisor</span><span class="role-pill">Manager</span></div></div><button class="btn quiet small" data-action="team">${pendingCount()?`Review ${pendingCount()} pending account${pendingCount()===1?'':'s'}`:'View team'} ${icon('arrow')}</button></aside></div>${state.user?`<div class="hub-overview"><section><div class="section-title"><div><h2>At the docks</h2><p>The latest trailer status across docks 16–19.</p></div><a class="text-link" href="${links.dock}">View board ${icon('arrow')}</a></div><div class="mini-grid">${DOCKS.map(id=>{let d=dock(id),s=statusOf(d);return `<a class="mini-dock" href="${links.dock}" style="color:${s.color}"><div><strong style="color:var(--text)">Dock ${id}</strong><small>${s.label}</small></div><span class="status-dot"></span></a>`}).join('')}</div></section><section><div class="section-title"><div><h2>Scanner fleet</h2><p>20 devices. A record of every handoff.</p></div><a class="text-link" href="${links.scanner}">View scanners ${icon('arrow')}</a></div><a class="hub-equipment-summary card" href="${links.scanner}"><img src="${asset('scanner-icon.svg')}" alt=""><div><b>${available} available</b><span>${out} checked out · ${20-scanners.length} unconfirmed</span><small>Open equipment dashboard ${icon('arrow')}</small></div></a></section></div>`:`<div class="card hub-signin"><div><b>Your team workspace</b><p>Sign in to view live docks, scanner checkouts, and your messages.</p></div><button class="btn secondary" data-action="account">${state.account?'View account':'Sign in'} ${icon('arrow')}</button></div>`}`;
}
function scene(d){const id=d.dockId,s=statusOf(d),filled=d.status==='loading'||d.status==='ready',present=['empty','loading','ready'].includes(d.status),ready=d.status==='ready';return `<svg class="dock-scene" viewBox="0 0 270 175" role="img" aria-label="Dock ${id}: ${s.label}"><defs><linearGradient id="wall-${id}" x2="0" y2="1"><stop stop-color="var(--soft)"/><stop offset="1" stop-color="var(--bg)"/></linearGradient></defs><path d="M0 0h270v175H0z" fill="var(--bg)"/><path d="M13 18h244v123H13z" fill="url(#wall-${id})"/><path d="M13 39h244M13 60h244M13 81h244M13 102h244" stroke="var(--line)" stroke-width="1"/><path d="M69 35h128v110H69z" fill="#73827a"/><path d="M77 42h112v99H77z" fill="${present?'#34483c':'#a4b2a4'}"/>${!present?`<path d="M80 55h106M80 68h106M80 81h106M80 94h106M80 107h106M80 120h106" stroke="#c8d3c7" stroke-width="3"/><path d="m122 130 11-8 11 8" fill="none" stroke="#e8ece6" stroke-width="2"/>`:''}<path d="M58 144h151l34 27H26z" fill="var(--line)" opacity=".45"/><rect x="109" y="15" width="49" height="22" rx="4" fill="var(--surface)"/><text x="134" y="31" text-anchor="middle" font-family="sans-serif" font-size="16" font-weight="700" fill="var(--text)">${id}</text><rect x="206" y="42" width="11" height="27" rx="4" fill="#3b4e41"/><circle cx="211.5" cy="50" r="3.5" fill="${ready?'#a4df78':'#536957'}"/><circle cx="211.5" cy="61" r="3.5" fill="${ready?'#536957':d.status==='loading'?'#f0b34c':'#cbd5cd'}"/>${present?`<path d="m82 65 18-17h71l15 17v76l-15 21h-71l-18-21z" fill="#f6f7f0" stroke="#b7c3b7" stroke-width="1.5"/><path d="M89 67h90v73H89z" fill="${ready?'#e3e9de':'#667a65'}"/>${ready?'<path d="M92 80h84M92 90h84M92 100h84M92 110h84M92 120h84M92 130h84" stroke="#b9c7b6" stroke-width="2"/><path d="M126 72v65m18-65v65" stroke="#8d9e89" stroke-width="2"/><rect x="129" y="111" width="12" height="13" rx="2" fill="#08643b"/><path d="M132 111v-4a3 3 0 0 1 6 0v4" fill="none" stroke="#08643b" stroke-width="2"/>':filled?'<path d="M96 121h77v12H96z" fill="#758d9b"/><path d="M99 99h23v22H99zM125 99h23v22h-23zM151 99h19v22h-19zM111 76h23v22h-23zM137 76h24v22h-24z" fill="#b9c888" stroke="#60784c" stroke-width="1.3"/><path d="M106 109h9m17 0h9m15 0h9m-48-23h10m16 0h10" stroke="#f2edce" stroke-width="4"/>':'<path d="M93 74h81v59H93z" fill="#879985"/><path d="m93 133 18-59h47l16 59" fill="none" stroke="#a7b4a0" stroke-width="1.4"/><path d="M97 118h73M101 103h65M105 88h57" stroke="#a7b4a0" stroke-width="1.4"/>'}<path d="M89 142h90l-11 14h-67z" fill="#d2dacb"/><path d="M100 158v10m70-10v10" stroke="#34483c" stroke-width="9" stroke-linecap="round"/><path d="M92 146h8m69 0h8" stroke="#cf7368" stroke-width="4"/>`:''}<path d="m45 155-8 14m190-14 8 14" stroke="#c6b766" stroke-width="4"/>${d.status==='unconfirmed'?'<text x="134" y="99" text-anchor="middle" font-family="sans-serif" font-size="31" fill="#e9eee5">?</text>':''}</svg>`}
function dockCard(id){const d=dock(id),s=statusOf(d);return `<article class="dock-card card" style="--status-color:${s.color}"><div class="dock-card-top"><strong>Dock ${id}</strong><span class="status-tag"><span class="dot"></span>${s.tag}</span></div>${scene(d)}<div class="dock-card-body"><h3>${s.label}</h3><p class="dock-next">${s.next}</p><div class="dock-meta"><span>${d.trailerId?`Trailer <b>${escape(d.trailerId)}</b>`:'Trailer —'}</span><span>${d.updatedAt?escape(time(d.updatedAt)):'No confirmed update'}</span></div><button class="btn secondary" data-action="dock" data-id="${id}">${permission('dock.update')?'View / update':'View details'} ${icon('arrow')}</button></div></article>`}
function dockList(){return `<div class="dock-list-shell card"><table class="dock-list-table"><caption class="sr-only">Dock status and latest updates for docks 16 through 19</caption><thead><tr><th scope="col">Dock</th><th scope="col">Status</th><th scope="col">Trailer</th><th scope="col">Last update</th><th scope="col">Next action</th><th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody>${DOCKS.map(id=>{const d=dock(id),s=statusOf(d);return `<tr style="--status-color:${s.color}"><td class="list-dock"><button class="plain-link" data-action="dock" data-id="${id}">${icon('dock')}Dock ${id}</button></td><td class="list-status"><span class="status-tag"><span class="dot"></span>${s.label}</span></td><td class="list-trailer" data-label="Trailer">${escape(d.trailerId||'—')}</td><td class="list-updated" data-label="Last update"><span>${d.updatedAt?escape(time(d.updatedAt,true)):'Unconfirmed'}</span><small>${escape(d.updatedByName||'')}</small></td><td class="list-next" data-label="Next action">${s.next}</td><td class="list-actions"><button class="btn secondary small" data-action="dock" data-id="${id}">${permission('dock.update')?'View / update':'View details'} ${icon('arrow')}</button></td></tr>`}).join('')}</tbody></table></div>`}
function activity(){const events=allEvents().slice(0,5);return `<section class="activity-panel card"><div class="section-title"><div><h2>Recent activity</h2><p>Every update has a person and a time.</p></div><span class="label">Last 72 hours</span></div>${events.length?events.map(e=>`<div class="activity-row"><span class="activity-icon">${icon(eventStatus(e)==='ready'?'lock':'history')}</span><div class="activity-info"><b>Dock ${e.dockId}</b> · ${escape(STATUS[eventStatus(e)]?.label||'Status updated')}<small>${escape(actor(e))}${eventRole(e)?' · '+escape(eventRole(e)):''}${e.note?' · '+escape(e.note):''}</small></div><span class="activity-time">${escape(time(e.createdAt||e.timestamp||e.updatedAt,true))}</span></div>`).join(''):'<div class="empty-state">No updates in the last 72 hours. Open a dock to confirm its status.</div>'}</section>`}
function board(){return `<div class="contextbar"><a class="eyebrow" href="${links.hub}">${icon('home')}Suja Life Tools</a><span class="clock-note">${escape(nowStamp())}</span></div><div class="board-title"><div><span class="eyebrow">Operations / Trailer flow</span><h1>Suja Dock Status</h1><p>A clear view of every trailer. A clear next move for the team.</p></div><span class="live-indicator"><span class="dot"></span>${state.mode==='setup'?'Setup pending':!state.user?(state.account?'Awaiting approval':'Sign in to view docks'):state.connected?'Live updates':'Reconnecting'}</span>${viewToggle('dock')}</div>${!state.user?`<section class="gate card"><div><span class="eyebrow">Docks 16 · 17 · 18 · 19</span><h2>Keep the next trailer moving.</h2><p>See which docks are empty, which trailers are loading, and which are locked and ready for shipping.</p><div class="button-row"><button class="btn" data-action="account">${state.account?'View account':'Sign in'} ${icon('arrow')}</button>${!state.account?'<button class="btn secondary" data-action="create-account">Create account</button>':''}</div><div class="setup-note">Use your display name and passphrase. Live dock data is available to approved team accounts.</div></div><img src="${asset('dock-hero.webp')}" alt="Suja Dock Status illustrated warehouse bays"></section>`:`<div class="summary-strip card">${['ready','loading','empty','no_trailer'].map(k=>`<div class="summary-item"><b style="color:${STATUS[k].color}">${DOCKS.filter(id=>dock(id).status===k).length}</b><span>${STATUS[k].short}</span></div>`).join('')}</div>${views.dock==='list'?dockList():`<section class="dock-grid" aria-label="Dock statuses">${DOCKS.map(dockCard).join('')}</section>`}<div class="process">${icon('dock')}<b>The trailer cycle</b><span>Empty trailer</span>${icon('arrow')}<span>Loading</span>${icon('arrow')}<span>Locked / ready</span>${icon('arrow')}<span>Pickup + replacement</span></div>${activity()}`}`}
function render(){const app=$('#app');app.innerHTML=header()+`<main class="container">${banner()}${page==='hub'?hub():page==='scanner'?scannerUI.render(state):board()}${footer()}</main>`;app.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>action(el.dataset.action,el.dataset.id)));refreshPreferenceDialog();if(page==='scanner')scannerUI.afterRender(state);teamUI?.refresh?.(state)}
function dialog(title,body,wide=false){document.querySelectorAll('dialog').forEach(d=>{d.close();d.remove()});const d=document.createElement('dialog');d.className='dialog'+(wide?' wide':'');d.innerHTML=`<div class="dialog-head"><h2>${escape(title)}</h2><button class="close-btn" aria-label="Close">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;document.body.append(d);$('.close-btn',d).onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.showModal();return d}
function errorIn(d,msg){let e=$('.form-error',d);if(e){e.innerHTML=`<div class="error">${escape(msg)}</div>`;e.scrollIntoView({block:'nearest'})}else toast(msg)}
function formBusy(form,busy){form.querySelectorAll('button[type=submit]').forEach(b=>{b.disabled=busy;b.textContent=busy?'Saving…':b.dataset.label||'Save'})}
async function action(a,id){try{if(a==='view'){const [key,value]=id.split(':');if(!['hub','dock'].includes(key)||!['grid','list'].includes(value))return;views[key]=value;try{localStorage.setItem(`sujaTools.view.${key}`,value)}catch{}render();document.querySelector(`[data-action="view"][data-id="${key}:${value}"]`)?.focus()}else if(a==='theme'){const v=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=v;localStorage.setItem('sujaTheme',v);render()}else if(a==='account')account();else if(a==='create-account')account('create');else if(a==='dock')dockDialog(id);else if(a==='messages')messages();else if(a==='team')team();else if(a==='share'){const key=id||page,url=links[key]||links.hub;if(navigator.share){try{await navigator.share({title:key==='scanner'?'Suja Scanner Status':key==='dock'?'Suja Dock Status':'Suja Life Tools',url})}catch(e){if(e.name!=='AbortError')throw e}}else{await navigator.clipboard.writeText(url);toast('Link copied')}}}catch(e){toast(e.message||'Please try again')}}
function account(mode='login'){
  if(state.user){
    const d=dialog('Your account',`<div class="account-info"><span class="avatar">${escape(state.user.displayName.slice(0,1))}</span><div><h3>${escape(state.user.displayName)}</h3><p>${escape(roleName(state.user))} · Suja Life Tools</p></div></div><p class="muted" style="font-size:13px">Your account is shared across every Suja Life tool.</p><label for="account-uid">Account UID</label><input id="account-uid" readonly value="${escape(state.user.uid)}"><p class="field-note">Your project owner uses this identifier for initial Master setup.</p><div class="button-row account-buttons"><button class="btn secondary account-alerts">${icon('message')}Alert preferences</button><button class="btn secondary logout">${icon('logout')}Sign out</button></div>`);
    $('.account-alerts',d).onclick=()=>alertPreferences();$('.logout',d).onclick=async()=>{d.close();await platform.logout()};return;
  }
  if(state.account){
    const a=state.account;
    const d=dialog('Account setup',`<div class="account-info"><span class="avatar">${escape(a.displayName?.slice(0,1)||'S')}</span><div><h3>${escape(a.displayName||'Your account')}</h3><p>Waiting for ${a.needsMasterSetup?'workspace setup':'Master approval'}</p></div></div><p class="muted" style="font-size:13px">Your sign-in is saved. Dock data becomes available when your account is approved.</p><label for="pending-uid">Your account UID</label><input id="pending-uid" readonly value="${escape(a.uid)}"><div class="button-row" style="margin-top:12px"><button class="btn secondary small copy-uid">Copy UID</button><button class="btn quiet small refresh-account">Reload workspace</button></div>${a.needsMasterSetup?`<details class="master-setup"><summary>First workspace setup</summary><p>The Firebase project owner sets this account's UID as the workspace Master. This is a one-time step in <b>Realtime Database → Data</b>.</p><p>Under <code>toolsV2</code>, create <code>config</code>, then a string named <code>masterUid</code> with the UID shown above. Publish the version 2 database rules first.</p><p>Refresh your account after saving. Only a Firebase project owner can make this initial assignment.</p></details>`:''}<div class="form-error" role="alert">${state.error?`<div class="error">${escape(state.error.message||state.error)}</div>`:''}</div><div class="form-actions"><button class="btn secondary logout">${icon('logout')}Sign out</button></div>`);
    $('.copy-uid',d).onclick=async()=>{try{await navigator.clipboard.writeText(a.uid);toast('Account UID copied')}catch{const input=$('#pending-uid',d);input.focus();input.select();toast('Select and copy the UID shown above')}};
    $('.refresh-account',d).onclick=()=>location.reload();$('.logout',d).onclick=async()=>{try{await platform.logout();d.close()}catch(e){errorIn(d,e.message)}};return;
  }
  const setup=state.mode==='setup',creating=mode==='create';
  const d=dialog(creating?'Create your account':'Welcome to Suja Life Tools',`<div class="tabs"><button type="button" data-auth-tab="login" class="${!creating?'active':''}">Sign in</button><button type="button" data-auth-tab="create" class="${creating?'active':''}">Create account</button></div><p class="muted" style="font-size:13px;margin-top:0">${creating?'Choose a display name and a password or passphrase. Your Master approves access and assigns your role.':'Use your display name and password or passphrase.'}</p>${setup?'<div class="setup-note">The workspace configuration is not available. Contact your project administrator.</div>':''}<form id="login-form"><label for="login-name">Display name</label><input id="login-name" name="displayName" autocomplete="username" required minlength="2" maxlength="48" placeholder="Your display name"><label for="login-pass">Password / passphrase</label><input id="login-pass" name="passphrase" type="password" autocomplete="${creating?'new-password':'current-password'}" required ${creating?'minlength="8" maxlength="128"':''} placeholder="${creating?'At least 8 characters':'Your password or passphrase'}">${creating?'<p class="field-note">Display names are unique. Capitalization and extra spaces do not create a different account.</p>':''}<div class="form-error" role="alert"></div><div class="form-actions"><button class="btn" type="submit" data-label="${creating?'Create account':'Sign in'}" ${setup?'disabled':''}>${creating?'Create account':'Sign in'}</button></div></form><p class="field-note">${creating?'Already have an account? Choose Sign in above.':'Need a password reset? Contact your Firebase project administrator.'}</p>`);
  d.querySelectorAll('[data-auth-tab]').forEach(b=>b.onclick=()=>account(b.dataset.authTab));
  $('#login-form',d).onsubmit=async e=>{
    e.preventDefault();if(setup)return;const form=e.currentTarget,f=new FormData(form);formBusy(form,true);
    try{if(creating)await platform.createAccount(f.get('displayName'),f.get('passphrase'));else await platform.login(f.get('displayName'),f.get('passphrase'));d.close();if(state.account&&!state.user)account();else toast('Welcome back')}
    catch(err){if(state.account&&!state.user){d.close();account()}else errorIn(d,err.message)}finally{if(d.isConnected)formBusy(form,false)}
  };
}
function requireUser(){if(!state.user){account();return false}return true}
function fitActionDialog(d,className){
  d.classList.add('dialog-with-actions',className);
  const viewport=window.visualViewport;
  const fit=()=>{
    if(!d.isConnected)return;
    const visibleHeight=viewport?.height||window.innerHeight,height=Math.max(140,Math.min(780,visibleHeight-16));
    d.style.setProperty('--action-dialog-height',`${height}px`);
    d.style.setProperty('--action-dialog-top',`${(viewport?.offsetTop||0)+Math.max(8,(visibleHeight-height)/2)}px`);
  };
  fit();window.addEventListener('resize',fit);viewport?.addEventListener('resize',fit);viewport?.addEventListener('scroll',fit);
  d.addEventListener('close',()=>{window.removeEventListener('resize',fit);viewport?.removeEventListener('resize',fit);viewport?.removeEventListener('scroll',fit);},{once:true});
}
function dockDialog(id,tab='update'){if(!requireUser())return;const captured={...dock(id)},s=statusOf(captured),canEdit=permission('dock.update');if(!canEdit)tab='history';const events=historyEvents(id);const d=dialog(`Dock ${id}`,`${tab==='update'?'<form id="dock-form"><div class="dock-form-scroll">':''}<div class="dock-detail-top"><span class="activity-icon" style="color:${s.color}">${icon(captured.status==='ready'?'lock':'dock')}</span><div><h3>${s.label}</h3><p>${captured.trailerId?'Trailer '+escape(captured.trailerId)+' · ':''}${captured.updatedAt?escape(time(captured.updatedAt,true)):'Status has not been confirmed'}</p></div></div><div class="tabs">${canEdit?`<button type="button" data-tab="update" class="${tab==='update'?'active':''}">Update status</button>`:''}<button type="button" data-tab="history" class="${tab==='history'?'active':''}">History (${events.length})</button></div>${tab==='history'?`<p class="history-caption">Rolling 72 hours. Every saved change records the person, role, and Pacific time.</p>${events.length?events.map(e=>`<div class="history-item"><p><b>${escape(STATUS[e.fromStatus]?.label||'Unconfirmed')}</b> → <b>${escape(STATUS[eventStatus(e)]?.label||'Updated')}</b></p><small>${escape(actor(e))} · ${escape(eventRole(e))} · ${escape(time(e.createdAt||e.timestamp||e.updatedAt,true))}</small>${e.trailerId?`<p style="font-size:11px;margin-top:5px">Trailer ${escape(e.trailerId)}</p>`:''}${e.note?`<p class="history-note">${escape(e.note)}</p>`:''}</div>`).join(''):'<div class="empty-state">No updates during the last 72 hours.</div>'}`:`<label>New status</label><div class="status-options">${Object.entries(STATUS).filter(([k])=>k!=='unconfirmed').map(([k,v])=>`<button class="status-option ${captured.status===k?'selected':''}" type="button" data-status="${k}" aria-pressed="${captured.status===k}"><span class="status-dot" style="color:${v.color}"></span>${v.label}</button>`).join('')}</div><input type="hidden" name="status" value="${captured.status==='unconfirmed'?'':captured.status}"><label for="trailer-id">Trailer number <span class="muted">(optional)</span></label><input id="trailer-id" name="trailerId" maxlength="40" value="${escape(captured.trailerId||'')}" placeholder="Enter trailer number"><label for="dock-note">Update note <span class="muted">(optional)</span></label><textarea id="dock-note" name="note" maxlength="500" placeholder="Anything the next person needs to know"></textarea><label id="locked-check" style="display:${captured.status==='ready'?'flex':'none'};gap:9px;align-items:flex-start"><input type="checkbox" name="lockedConfirmed" style="width:17px;margin-top:2px"><span>I confirmed this trailer is full, locked, and ready for pickup.</span></label><div class="setup-note" id="next-action">${s.next}</div><div class="field-note">Saved as ${escape(state.user.displayName)} · ${escape(roleName(state.user))}. A ready trailer creates a shipping update in the message center.</div><div class="form-error" role="alert"></div></div><div class="form-actions dock-save-actions"><button class="btn secondary cancel" type="button">Cancel</button><button class="btn" type="submit" data-label="Save update" ${!state.connected?'disabled':''}>Save update</button></div></form>`}`);d.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>dockDialog(id,b.dataset.tab));if(tab==='update'){fitActionDialog(d,'dock-update-dialog');$('.cancel',d).onclick=()=>d.close();d.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{const k=b.dataset.status;$('[name=status]',d).value=k;d.querySelectorAll('[data-status]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});$('#locked-check',d).style.display=k==='ready'?'flex':'none';$('#next-action',d).textContent=STATUS[k].next;$('#trailer-id',d).disabled=k==='no_trailer';if(k==='no_trailer')$('#trailer-id',d).value=''});$('#dock-form',d).onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),newStatus=f.get('status');if(!newStatus)return errorIn(d,'Choose a dock status.');if(newStatus==='ready'&&!f.get('lockedConfirmed'))return errorIn(d,'Confirm that the trailer is full, locked, and ready for pickup.');formBusy(form,true);try{await platform.updateDock({dockId:id,status:newStatus,trailerId:newStatus==='no_trailer'?'':f.get('trailerId'),note:f.get('note'),expectedRevision:captured.revision||0,lockedConfirmed:!!f.get('lockedConfirmed')});d.close();toast(`Dock ${id} updated · ${STATUS[newStatus].label}`)}catch(err){errorIn(d,err.message)}finally{if(d.isConnected)formBusy(form,false)}}}}
function preferenceSyncNote(){
  if(state.notificationPreferencesSync==='loading')return 'Loading your alert preferences…';
  return state.notificationPreferencesSync==='synced'?'These choices follow your account across Suja Life tools.':'Saved on this device. Account sync is currently unavailable.';
}
function refreshPreferenceDialog(){
  const form=$('#notification-preferences-form');if(!form)return;
  if(form.dataset.uid!==state.user?.uid){form.closest('dialog')?.close();return;}
  const loading=state.notificationPreferencesSync==='loading';
  if(form.dataset.loading==='true'&&!loading){
    const prefs=normalizeNotificationPreferences(state.notificationPreferences);
    for(const key of Object.keys(prefs.statuses))form.elements[`status_${key}`].checked=prefs.statuses[key];
    for(const key of ['teamMessages','roleMessages','directMessages'])form.elements[key].checked=prefs[key];
    form.dataset.loading='false';
  }
  form.querySelectorAll('fieldset').forEach(field=>field.disabled=loading||form.dataset.busy==='true');
  form.querySelector('button[type=submit]').disabled=loading||form.dataset.busy==='true';
  $('.preference-sync-note',form).textContent=preferenceSyncNote();
}
function alertPreferences(fromMessages=false){
  if(!requireUser())return;
  const prefs=normalizeNotificationPreferences(state.notificationPreferences),loading=state.notificationPreferencesSync==='loading';
  const statuses=[['no_trailer','No trailer at the dock','A dock is available and needs a trailer.'],['empty','Empty trailer','An empty trailer is available for loading.'],['loading','Trailer being filled','Product is being loaded into the trailer.'],['ready','Locked / ready for pickup','The full trailer is locked and ready for shipping.']];
  const messageTypes=[['teamMessages','Team messages','Messages addressed to the whole team.'],['roleMessages','Role messages','Messages addressed to your assigned role.'],['directMessages','Direct messages','Messages addressed specifically to you.']];
  const option=(key,label,description,checked)=>`<label class="preference-option"><input type="checkbox" name="${key}" ${checked?'checked':''}><span><b>${label}</b><small>${description}</small></span></label>`;
  const tabs=fromMessages?`<div class="tabs message-tabs"><button type="button" data-tab="inbox">Inbox ${unread()?`(${unread()})`:''}</button>${permission('message.send')?'<button type="button" data-tab="compose">Compose</button>':''}<button type="button" data-tab="preferences" class="active" aria-current="page">Preferences</button></div>`:'';
  const d=dialog('Alert preferences',`<form id="notification-preferences-form" data-uid="${escape(state.user.uid)}" data-loading="${loading}"><div class="preference-form-scroll">${tabs}<p class="preference-intro">Choose which dock alerts and messages appear in your personal inbox and unread count.</p><fieldset ${loading?'disabled':''}><legend>Dock status alerts</legend><p class="field-note">Updates for docks 16–19. Select any combination.</p><div class="preference-options">${statuses.map(([key,label,description])=>option('status_'+key,label,description,prefs.statuses[key])).join('')}</div></fieldset><fieldset ${loading?'disabled':''}><legend>Messages from the team</legend><div class="preference-options">${messageTypes.map(([key,label,description])=>option(key,label,description,prefs[key])).join('')}</div></fieldset><p class="field-note preference-scope">In-app messages only. You can turn every option off. The dock board and history always show every update.</p><p class="field-note preference-sync-note" role="status">${escape(preferenceSyncNote())}</p></div><div class="preference-save-footer"><div class="preference-save-status" role="status" aria-live="polite"></div><div class="form-error" role="alert"></div><div class="form-actions"><button class="btn" type="submit" data-label="Save preferences" ${loading?'disabled':''}>Save preferences</button></div></div></form>`);
  fitActionDialog(d,'alert-preferences-dialog');
  d.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>messages(button.dataset.tab));
  const form=$('#notification-preferences-form',d);
  form.onchange=()=>{$('.preference-save-status',form).textContent='';$('.form-error',form).textContent='';};
  form.onsubmit=async event=>{
    event.preventDefault();if(form.dataset.uid!==state.user?.uid)return errorIn(d,'Your account changed. Reopen your alert preferences.');
    const fields=new FormData(form),next={statuses:Object.fromEntries(statuses.map(([key])=>[key,fields.has('status_'+key)])),...Object.fromEntries(messageTypes.map(([key])=>[key,fields.has(key)]))};
    form.dataset.busy='true';formBusy(form,true);refreshPreferenceDialog();$('.form-error',form).textContent='';$('.preference-save-status',form).textContent='';
    try{
      const result=await platform.saveNotificationPreferences(next);
      if(!d.isConnected)return;
      $('.preference-save-status',form).textContent=result.synced?'Preferences saved to your account.':'Preferences saved on this device. Account sync is currently unavailable.';
      toast(result.synced?'Alert preferences saved':'Alert preferences saved on this device');
    }catch(error){if(d.isConnected)errorIn(d,error.message);}
    finally{if(d.isConnected){form.dataset.busy='false';formBusy(form,false);refreshPreferenceDialog();}}
  };
}
function messages(tab='inbox'){if(!requireUser())return;if(tab==='preferences'){alertPreferences(true);return;}const list=state.messages||[],roles=Object.values(state.roles||{}),users=Object.values(state.users||{});const d=dialog('Message center',`<div class="tabs message-tabs"><button data-tab="inbox" class="${tab==='inbox'?'active':''}">Inbox ${unread()?`(${unread()})`:''}</button>${permission('message.send')?`<button data-tab="compose" class="${tab==='compose'?'active':''}">Compose</button>`:''}<button data-tab="preferences">Preferences</button></div>${tab==='compose'?`<form id="message-form"><label for="message-to">Send to</label><select id="message-to" name="audience"><option value="team:">Whole team</option><optgroup label="Roles">${roles.map(r=>`<option value="role:${escape(r.id)}">${escape(roleAudienceLabel(r))}</option>`).join('')}</optgroup><optgroup label="People">${users.filter(u=>u.active!==false).map(u=>`<option value="user:${escape(u.uid)}">${escape(u.displayName)}</option>`).join('')}</optgroup></select><label for="message-body">Message</label><textarea id="message-body" name="body" required minlength="1" maxlength="1500" rows="5" placeholder="Keep the team in the loop"></textarea><div class="form-error" role="alert"></div><div class="form-actions"><button type="submit" class="btn" data-label="Send message">Send message ${icon('arrow')}</button></div></form>`:`${list.length?list.map(m=>`<article class="message-item ${!(m.read||m.readAt||m.readBy?.[state.user.uid])?'unread':''}"><div class="message-top"><b>${escape(m.senderName||m.authorName||m.fromName||'Dock updates')}</b><span>${escape(time(m.createdAt,true))}</span></div><p>${escape(m.body||m.text)}</p><div style="display:flex;justify-content:space-between;align-items:center"><small class="muted">${escape(messageAudienceLabel(m))}${m.scannerId?` <a class="text-link" href="${links.scanner}#device=${encodeURIComponent(m.scannerId)}">View scanner</a>`:''}${m.noticeType==='pending_account'?'<button class="btn quiet small review-account" type="button">Review account</button>':''}</small>${!(m.read||m.readAt||m.readBy?.[state.user.uid])?`<button class="btn quiet small mark-read" data-id="${escape(m.id)}">Mark read ${icon('check')}</button>`:'<small class="muted">Read</small>'}</div></article>`).join(''):'<div class="empty-state">You’re all caught up. Messages matching your alert preferences appear here.</div>'}`}`,true);d.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>messages(b.dataset.tab));d.querySelectorAll('.review-account').forEach(button=>button.onclick=()=>team('pending'));d.querySelectorAll('.mark-read').forEach(b=>b.onclick=async()=>{try{await platform.markRead(b.dataset.id);messages()}catch(e){errorIn(d,e.message)}});if(tab==='compose')$('#message-form',d).onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),[audienceType,audienceId]=f.get('audience').split(':');formBusy(form,true);try{await platform.sendMessage({body:f.get('body'),audienceType,audienceId});messages();toast('Message sent')}catch(err){errorIn(d,err.message);formBusy(form,false)}}}
const PERMISSIONS={'dock.update':'Update dock status','message.send':'Send team messages'};
function team(tab='people'){if(!requireUser())return;teamUI.open(tab)}
window.addEventListener('storage',e=>{if(e.key?.startsWith('sujaTools.view.')){const key=e.key.slice('sujaTools.view.'.length);if(key in views){views[key]=e.newValue==='list'?'list':'grid';render()}}if(e.key==='sujaTheme'){document.documentElement.dataset.theme=e.newValue||'light';render()}});
setInterval(()=>{document.querySelectorAll('.clock-note').forEach(e=>e.textContent=nowStamp())},30000);
